customCSS:
.t, .history { color: #4e5157; }
.join { color: #7aa4a1; }
.part, .quit { color: #4e5157; }
.kick, .error { color: #e85c51; }
.notice { color: #fda47f; }
.action { color: #ad5c7c; }
.mode, .nick, .topic, .server { color: #a1cdd8; }
.highlight { color: #e6eaea; background-color: #293e40; border-left: 3px solid #ad5c7c; padding-left: 8px; }
.reply { color: #4e5157; border-left: 2px solid #5a93aa; padding-left: 6px; }
.oper { color: #152528; background-color: #fda47f; }
.reactions { color: #5a93aa; background-color: #2f3239; }
.card { background-color: #2f3239; border-color: #4e5157; }
.card-title { color: #5a93aa; }
.card-desc { color: #4e5157; }
.daychange { color: #4e5157; border-color: #2f3239; }
